319	/**
320	 * The claims on a sheet: added to a person and edited (amount, date, note, external reference). A
321	 * claim's reference, when it has one, is unique on its sheet without regard to case. A claim given no date
322	 * takes the sheet's today. A claim starts as DRAFT and moves through its statuses (see
323	 * {@link ClaimStatus}); a change its status does not allow is refused. Only a DRAFT can be edited:
324	 * to change an open claim, void it and add a new one. Settling a claim fixes its
325	 * due at the rate its person's grade has then for the claim's date; an open claim's due stays live.
326	 * A claim records who opened it, and that user cannot settle it (four eyes). A claim bound by its
327	 * person's last statement keeps the figure it had then, and settling it fixes that figure. A claim
328	 * belongs to the period its due-by falls in (fixed at creation: an edit, re-date or move leaves it).
329	 * No claim due inside a closed period can be added, edited or change status. No
330	 * claim can be added or edited to a date after its person's retirement date. A clerk settles a claim
331	 * only when its figure is at or below the sheet's clerk limit (a claim with no figure is within any
332	 * limit); a clerk settling one above it makes it PENDING instead. A steward settles any claim, and
333	 * approves a PENDING claim (SETTLED, its due fixed then) or rejects it with a reason (back to OPEN);
334	 * the user who opened a claim cannot approve it. A PENDING claim is not bound by a statement: it
335	 * shows its live figure, and is bound again by the last statement once rejected. An overdue claim's due gains a late charge on its
336	 * figure (see {@link LateCharge}), and the floor is applied last: a claim's live due is never below
337	 * the sheet's floor. A statement binds only the rate figure, not the charge nor the floor, and settling fixes the charge into the settled due. A claim with
338	 * a negative amount is a correction: it is allowed only when it names, by number, a SETTLED claim
339	 * of the same person that it corrects. Its due has no floor and no late charge. A steward can move
340	 * a DRAFT, OPEN or PENDING claim to another person: it keeps its number and date, loses any figure
341	 * a statement bound it to, and is listed as its new person's newest claim. A steward can re-settle
342	 * a SETTLED claim: its due is fixed again at the figure it would have today as an open claim bound
343	 * by no statement (today's rates, grades, floor and late charge). An OPEN claim can be deferred to
344	 * a date after the sheet's today: until the sheet's today reaches it the claim counts in no total,
345	 * is not overdue, cannot be settled and is left unbound by a statement; from then on it is an OPEN
346	 * claim like any other. A claim has a proofs count, raised by one at a time while it is not SETTLED
347	 * or VOID. An OPEN claim can be split: an amount split off it becomes a new OPEN claim (see
348	 * {@link #split}). A claim whose figure is above the proof threshold in force on its date cannot be settled
349	 * or approved while it has no proofs: that is refused before the clerk limit is considered. A claim
350	 * whose due is above the note threshold in force on its date cannot be opened while its note is empty.
351	 * Who may open, settle, void or move a claim is the sheet's permission matrix (see
352	 * {@link Sheet#permits}): an action the user's role may not take is refused (403). When a claim is
353	 * settled, approved or re-settled, each user watching its person is notified, in the order they
354	 * started watching. A steward may void a SETTLED claim within {@value #VOID_SETTLED_DAYS} days of its
355	 * settlement (the date its status log records it SETTLED) by the sheet's today: it keeps its number and
356	 * its frozen figure, which leaves every total.
357	 */
358	@Service
359	public class ClaimService {
360	
361	    /** How many days after its settlement a steward may still void a SETTLED claim. */
362	    static final int VOID_SETTLED_DAYS = 7;
363	
364	    private final ClaimRepository claims;
365	    private final PersonRepository people;
366	    private final RateRepository rates;
367	    private final SheetService sheets;
368	    private final Audit audit;
369	    private final RollupService rollup;
370	    private final PeriodService periods;
371	    private final RoleService roles;
372	    private final WatchRepository watches;
373	    private final HolidayService holidays;
374	    private final UsedTagRepository usedTags;
375	    private final VoidReasonService voidReasons;
376	
377	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates, SheetService sheets,
378	            Audit audit, RollupService rollup, PeriodService periods, RoleService roles, WatchRepository watches,
379	            HolidayService holidays, UsedTagRepository usedTags, VoidReasonService voidReasons) {
380	        this.voidReasons = voidReasons;
381	        this.holidays = holidays;
382	        this.usedTags = usedTags;
383	        this.roles = roles;
384	        this.watches = watches;
385	        this.rollup = rollup;
386	        this.periods = periods;
387	        this.claims = claims;
388	        this.people = people;
389	        this.rates = rates;
390	        this.sheets = sheets;
391	        this.audit = audit;
392	    }
393	
394	    /**
395	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
396	     * statement (not while PENDING), else the live due; null when it has none.
397	     */
398	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
399	        if (isFrozen(claim)) {
400	            return claim.getSettledDue();
401	        }
402	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
403	                : due(sheetId, person, claim);
404	    }
405	
406	    /** Whether the claim's figure is the due fixed when settled: SETTLED, or VOID once settled. */
407	    private static boolean isFrozen(Claim claim) {
408	        return claim.getStatus() == ClaimStatus.SETTLED
409	                || (claim.getStatus() == ClaimStatus.VOID && claim.getSettledDue() != null);
410	    }
411	
412	    /**
413	     * A claim's due on the sheet's today: the due fixed when settled, else its figure with its late
414	     * charge added on top, raised to the floor (see {@link LateCharge}); null when it has none.
415	     */
416	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
417	        if (isFrozen(claim)) {
418	            return claim.getSettledDue();
419	        }
420	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, person.gradeOn(claim.getDate()), figure(sheetId, person, claim));
421	    }
422	
423	    /**
424	     * A claim's due-by, fixed at creation: its date plus the first of the person's own terms, the
425	     * terms of their grade and the sheet's terms, each as in force on its date, counted in business
426	     * days: skipping every Saturday, Sunday and holiday on the sheet.
427	     */
428	    private LocalDate dueBy(String sheetId, Person person, LocalDate dated) {
429	        Integer own = person.getTerms();
430	        return holidays.businessDaysAfter(sheetId, dated,
431	                own != null ? own : sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated));
432	    }
433	
434	    @Transactional(readOnly = true)
435	    public List<Claim> list(String sheetId) {
436	        return claims.findBySheetIdOrderByListedDesc(sheetId);
437	    }
438	
439	    @Transactional
440	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
441	            String corrects, String ref, List<String> tags) {
442	        roles.refuseViewer(sheetId, user);
443	        Person person = person(sheetId, personId);
444	        LocalDate dated = dateOrToday(sheetId, date);
445	        LocalDate dueBy = dueBy(sheetId, person, dated);
446	        periods.refuseIfClosed(sheetId, dueBy);
447	        refuseIfRetired(person, dated);
448	        String corrected = corrected(sheetId, personId, amount, corrects);
449	        refuseIfRefUsed(sheetId, ref, null);
450	        RollupService.Snapshot before = rollup.snapshot(sheetId);
451	        Claim claim = new Claim(sheetId, personId, amount, dated, dueBy, note, corrected);
452	        claim.setRef(ref);
453	        claim.setTags(tags);
454	        claim.setLateEntry(periods.isSoftClosed(sheetId, dueBy));
455	        logStatus(sheetId, user, person, claim);
456	        Claim added = claims.saveAndFlush(claim);
457	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added)
458	                + (added.getRef() != null ? " ref=" + added.getRef() : "")
459	                + (added.getTags().isEmpty() ? "" : " tags=" + String.join(",", added.getTags())));
460	        useTags(sheetId, added);
461	        if (added.isLateEntry()) {
462	            audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, added));
463	        }
464	        rollup.recordChanges(sheetId, user, before);
465	        return added;
466	    }
467	
468	    @Transactional
469	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
470	            String corrects, String ref, List<String> tags) {
471	        roles.refuseViewer(sheetId, user);
472	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
473	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
474	        refuseIfNotEditable(sheetId, user, claim);
475	        LocalDate dated = dateOrToday(sheetId, date);
476	        periods.refuseIfClosed(sheetId, claim.getDueBy());
477	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
478	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
479	        refuseIfRefUsed(sheetId, ref, claim.getId());
480	        RollupService.Snapshot before = rollup.snapshot(sheetId);
481	        claim.setAmount(amount);
482	        claim.setRef(ref);
483	        claim.setTags(tags);
484	        claim.setDate(dated);
485	        claim.setNote(note);
486	        claim.setCorrects(corrected);
487	        claim.setLockedBy(null);
488	        Claim saved = claims.saveAndFlush(claim);
489	        useTags(sheetId, saved);
490	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
491	        rollup.recordChanges(sheetId, user, before);
492	        return saved;
493	    }
494	
495	    /**
496	     * Change a DRAFT claim's amount in its row, keeping its date, note and correction: refused
497	     * exactly as the claim form's save is, and recorded as CLAIM_EDITED as it is. An editor the
498	     * user has open on the claim stays open.
499	     */
500	    @Transactional
501	    public Claim updateAmount(String sheetId, String user, long id, BigDecimal amount) {
502	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
503	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
504	        String lockedBy = claim.getLockedBy();
505	        Claim saved = update(sheetId, user, id, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
506	                claim.getRef(), claim.getTags());
507	        saved.setLockedBy(lockedBy);
508	        return claims.saveAndFlush(saved);
509	    }
510	
511	    /**
512	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
513	     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
514	     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
515	     * claim takes no lock. Any other claim of the same person the user had locked is released.
516	     */
517	    @Transactional
518	    public Claim lock(String sheetId, String user, long id) {
519	        roles.refuseViewer(sheetId, user);
520	        // hold the sheet so two users cannot both take the lock
521	        sheets.lock(sheetId);
522	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
523	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
524	        refuseIfNotEditable(sheetId, user, claim);
525	        periods.refuseIfClosed(sheetId, claim.getDueBy());
526	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
527	            if (other.getId() != id && user.equals(other.getLockedBy())) {
528	                other.setLockedBy(null);
529	                claims.save(other);
530	            }
531	        }
532	        claim.setLockedBy(user);
533	        return claims.saveAndFlush(claim);
534	    }
535	
536	    /** Cancel a claim's editor: the user's lock on the claim is released; another user's lock stays. */
537	    @Transactional
538	    public Claim unlock(String sheetId, String user, long id) {
539	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
540	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
541	        if (user.equals(claim.getLockedBy())) {
542	            claim.setLockedBy(null);
543	            claim = claims.saveAndFlush(claim);
544	        }
545	        return claim;
546	    }
547	
548	    /** Refuse (409) editing a claim that is not DRAFT, or that another user's open editor locks. */
549	    private static void refuseIfNotEditable(String sheetId, String user, Claim claim) {
550	        if (claim.getStatus() != ClaimStatus.DRAFT) {
551	            throw new ResponseStatusException(HttpStatus.CONFLICT,
552	                    "A " + claim.getStatus() + " claim cannot be edited.");
553	        }
554	        if (claim.isLockedAgainst(user)) {
555	            throw new ResponseStatusException(HttpStatus.CONFLICT,
556	                    "This claim is being edited by " + claim.getLockedBy() + ".");
557	        }
558	    }
559	
560	    /**
561	     * Move a claim to a new status, refused (409) when its current status does not allow it,
562	     * refused (403) when the user who opened it tries to settle it, and refused (422) settling a
563	     * claim above the proof threshold with no proofs. A clerk settling one whose
564	     * figure is above the sheet's clerk limit makes it PENDING instead.
565	     */
566	    @Transactional
567	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
568	        return changeStatus(sheetId, user, id, next, null, false, null);
569	    }
570	
571	    /**
572	     * Void a claim, as {@link #changeStatus(String, String, long, ClaimStatus)}, with a reason from
573	     * the sheet's void reasons: while the sheet has any, a void without one of them is refused (422).
574	     */
575	    @Transactional
576	    public Claim voidClaim(String sheetId, String user, long id, String voidReason) {
577	        return changeStatus(sheetId, user, id, ClaimStatus.VOID, null, false, voidReason);
578	    }
579	
580	    /**
581	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
582	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
583	     * user who opened it.
584	     */
585	    @Transactional
586	    public Claim approve(String sheetId, String user, long id) {
587	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true, null);
588	    }
589	
590	    /**
591	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
592	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
593	     */
594	    @Transactional
595	    public Claim reject(String sheetId, String user, long id, String reason) {
596	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true, null);
597	    }
598	
599	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
600	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
601	            boolean review, String voidReason) {
602	        roles.refuseViewer(sheetId, user);
603	        if (!review) {
604	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
605	                case OPEN -> "open";
606	                case SETTLED -> "settle";
607	                case VOID -> "void";
608	                default -> throw new IllegalStateException();
609	            });
610	        }
611	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
612	        if (next == ClaimStatus.OPEN) {
613	            sheets.lock(sheetId);
614	        }
615	        RollupService.Snapshot before = rollup.snapshot(sheetId);
616	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
617	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
